from pathlib import Path
from PIL import Image
import io,base64,json,re
out=Path('Artifacts/RisographGame')
def uri(path):
 im=Image.open(path).convert('RGB');buf=io.BytesIO();im.save(buf,'WEBP',quality=95,method=5);return 'data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
keys=['character-155','character-180','character-210','detail','backlight']+[f'orbit-{i:02d}' for i in range(12)]
styles=['original','riso-old','riso-game','telltale','woodcut'];images={}
for key in keys:
 for style in styles:images[key+'-'+style]=uri(out/f'{key}-{style}.png')
for level in ['RoboticForest','LaboratoryFloor','CrystalGarden']:
 for style in ['original','riso-old','riso-game']:images['fps-'+level+'-'+style]=uri(out/f'fps-{level}-{style}.png')
